{
  "diagrams": [
    {
      "id": "sub_diagram_1",
      "domain": "State Machine",
      "summary": "A state machine diagram for a bitblt operation, showing transitions between states and a conditional loop.",
      "entities": [
        {
          "id": "e1",
          "label": "Sleep state",
          "type": "State",
          "location": "left"
        },
        {
          "id": "e2",
          "label": "Start bitblt",
          "type": "Transition",
          "location": "between Sleep state and read FIFO or read Host"
        },
        {
          "id": "e3",
          "label": "read FIFO or read Host",
          "type": "State",
          "location": "center-left"
        },
        {
          "id": "e4",
          "label": "process",
          "type": "State",
          "location": "center"
        },
        {
          "id": "e5",
          "label": "write FIFO or Host (once a words)",
          "type": "State",
          "location": "center-right"
        },
        {
          "id": "e6",
          "label": "If (color expan) counter!=done_number",
          "type": "Conditional Block",
          "location": "below process"
        },
        {
          "id": "e7",
          "label": "else",
          "type": "Else Block",
          "location": "below conditional block"
        },
        {
          "id": "e8",
          "label": "A bitblt operation is end",
          "type": "Terminal State",
          "location": "top"
        }
      ],
      "relations": [
        {
          "source": "e1",
          "target": "e3",
          "type": "transition",
          "details": "Triggered by 'Start bitblt'"
        },
        {
          "source": "e3",
          "target": "e4",
          "type": "flow",
          "details": "Sequential flow"
        },
        {
          "source": "e4",
          "target": "e5",
          "type": "flow",
          "details": "Sequential flow"
        },
        {
          "source": "e5",
          "target": "e6",
          "type": "conditional_branch",
          "details": "Branches to conditional check"
        },
        {
          "source": "e6",
          "target": "e3",
          "type": "conditional_flow",
          "details": "If condition is true, returns to 'read FIFO or read Host'"
        },
        {
          "source": "e7",
          "target": "e5",
          "type": "conditional_flow",
          "details": "Else branch leads to 'write FIFO or Host'"
        },
        {
          "source": "e5",
          "target": "e8",
          "type": "flow",
          "details": "After writing, operation ends"
        },
        {
          "source": "e8",
          "target": "e1",
          "type": "loop",
          "details": "After operation ends, system returns to 'Sleep state'"
        }
      ]
    }
  ]
}

