      "domain": "Semiconductor Physics / Photovoltaic Process",
      "summary": "Simplified diagram illustrating the generation and separation of electron-hole pairs under light irradiation in a semiconductor material.",
      "entities": [
        {"id": "e1", "label": "光", "type": "External Stimulus", "value": "Light", "location": "left side, entering the material"},
        {"id": "e2", "label": "e⁻", "type": "Electron", "value": "Electron", "location": "top of the material, moving left"},
        {"id": "e3", "label": "h⁺", "type": "Hole", "value": "Hole", "location": "bottom of the material, moving right"},
        {"id": "e4", "label": "e⁻", "type": "Electron", "value": "Electron", "location": "right side, exiting the material"},
        {"id": "e5", "label": "h⁺", "type": "Hole", "value": "Hole", "location": "left side, exiting the material"},
        {"id": "e6", "label": "Semiconductor Material", "type": "Material", "value": "Semiconductor", "location": "central rectangular block"}
      ],
      "relations": [
        {"source": "e1", "target": "e6", "type": "excites", "details": "Light excites electron-hole pairs within the semiconductor."},
        {"source": "e6", "target": "e2", "type": "generated_by", "details": "Electrons are generated within the material and move upward."},
        {"source": "e6", "target": "e3", "type": "generated_by", "details": "Holes are generated within the material and move downward."},
        {"source": "e2", "target": "e4", "type": "flows_to", "details": "Electrons flow from top to right side (external circuit)."},
        {"source": "e3", "target": "e5", "type": "flows_to", "details": "Holes flow from bottom to left side (external circuit)."}
      ]
    }
  ]
}

